                case "嫉妒":      return new string[] { "~g~"+name+":~s~ \"Okay. But you better not be seeing anyone else.\"", "~g~"+name+":~s~ \"Sure. Just me though, right?\"", "~g~"+name+":~s~ \"Alright. And I mean it — just us.\"" };
