                case "Mysterious":   return new string[] { "~g~"+name+":~s~ \"...Alright. Let's go.\"", "~g~"+name+":~s~ \"Sure. I had a feeling you'd ask.\"", "~g~"+name+":~s~ \"Fine. Don't read too much into it.\"" };
