                case "Sarcastic":   return new string[] { "~r~"+name+":~s~ \"Wow. No. Absolutely not.\"", "~r~"+name+":~s~ \"...Okay. No. Just no.\"", "~r~"+name+":~s~ \"That's way too much.\"" };
