                case "Independent": return new string[] { "~r~"+name+":~s~ \"I barely know you. Please stop.\"", "~r~"+name+":~s~ \"That's not something I can say back.\"", "~r~"+name+":~s~ \"I need you to pump the brakes.\"" };
