                case "Romantic":    return new string[] { "~r~"+name+":~s~ \"I want to feel that. I just... don't yet. I'm sorry.\"", "~r~"+name+":~s~ \"I wish I could say it back. I'm not there yet.\"", "~r~"+name+":~s~ \"That means everything. I just... need more time.\"" };
