                bool isIndoors = Function.Call<int>(Hash.GET_INTERIOR_FROM_ENTITY, Game.Player.Character) != 0;
                if (!isCar && !isIndoors && profEsc != null && profEsc.Riskiness < 0.40
                    && GetServicePriceGroup(false, menuIndex) != PriceGroup.Kissing)
