                            heading = 0f; 
                            isSitting = false; 
                            zOffset = 0f; 
                            rotX = 0f;
                            break;
                        default:
                            mDict = "amb@world_human_picnic@male@enter";   mAnim = "enter";
                            fDict = "amb@world_human_picnic@female@enter"; fAnim = "enter";
                            offset = new Vector3(-0.7f, 0.4f, 0.0f);
                            heading = 0f; 
                            isSitting = false; 
                            zOffset = 0f; 
                            rotX = 0f;
                            break;
                    }
                    break;
