                            fDict = VEH_NORM_DICT; fAnim = "into_proposition_prostitute";
                            offset = new Vector3(0.85f, -0.01f, -0.02f);
                            heading = 0f;
                            isSitting = true;
                            zOffset = -0.855f;
                            rotX = 5.0f;
                            break;
