                        if (RequestAnimDict(p2FD))
                            Function.Call(Hash.TASK_PLAY_ANIM, girl, p2FD, p2FA,
                                8.0f, -4.0f, -1, 2, 0f, false, false, false);
                    }
                    else
                        Function.Call(Hash.TASK_PLAY_ANIM, girl, iFDict, iFAnim,
                            8.0f, -4.0f, -1, 2, 0f, false, false, false);

