            else if (mood == "開心")   animName = "心情：開心";
            else if (mood == "戒備") animName = "心情：瞄準";
            else if (mood == "玩鬧") animName = "心情：得意";
            else if (mood == "惱怒") animName = "心情：憤怒";
            else if (mood == "依賴")   animName = "心情：緊張";
            else if (mood == "嫉妒") animName = "心情：受傷";
