                p = Path.Combine(SOUNDS_DIR, "BJSpit.wav");         if (CacheBjSound(p)) _bjSpitFile        = p;
                p = Path.Combine(SOUNDS_DIR, "BJPantsZip.wav");     if (CacheBjSound(p)) _bjPantsZipFile    = p;

                var slaps = new List<string>();
